import java.util.*;

public class Main {
    void invertedRightHalfPyramid(int n) {
        for (int i = 1; i <= n; i++) {                // row i needs n - i + 1 stars
            int stars = n - i + 1;
            for (int j = 0; j < stars; j++) {          // print each star in this row
                System.out.print("*");                    // one call per character
            }
            System.out.println();                     // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.invertedRightHalfPyramid(4);
    }
}

