            sb.append("*".repeat(n - i + 1));             // build every row directly, one operation each
            if (i < n) {
                sb.append('\n');
            }
        }
        System.out.println(sb);                        // output the whole pattern with a single call
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.invertedRightHalfPyramid(4);
    }
}

